```java
import java.io.*;
import java.util.regex.*;

public class CommandHandler {
    // This method is secure because it uses a ProcessBuilder with a 
    // parameterized array and validates input against a strict whitelist.
    public void pingHost(String host) {
        // 1. Validate input using a regular expression to ensure it's a valid IP/hostname only
        if (!Pattern.matches("^[a-zA-Z0-9.-]+$", host)) {
            System.out.println("Invalid input detected!");
            return;
        }

        try {
            // 2. Use ProcessBuilder with separate arguments. 
            // This prevents the shell from interpreting metacharacters like ';' or '&'.
            ProcessBuilder pb = new ProcessBuilder("ping", "-c", "4", host);
            Process process = pb.start();

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
```

